import{_ as t,o,c as r,a5 as n}from"./chunks/framework.Cct9zD0Q.js";const p=JSON.parse('{"title":"Remote Check Will Not Turn On","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/troubleshooting/remote-check.md","filePath":"manual/troubleshooting/remote-check.md","lastUpdated":1795599730000}'),a={name:"manual/troubleshooting/remote-check.md"};function i(s,e,h,c,d,l){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="remote-check-will-not-turn-on" tabindex="-1">Remote Check Will Not Turn On <a class="header-anchor" href="#remote-check-will-not-turn-on" aria-label="Permalink to &quot;Remote Check Will Not Turn On&quot;">​</a></h1><p><code>Turn on 1h</code> under <code>Remote check</code> at the bottom of <strong>Maintenance</strong> › <code>Robot Check</code> cannot be pressed, or pressing it does not turn remote check on. Work through the checks below in order. For how remote check works, see <a href="/RBQ/nightly/manual/gui/maintenance.html#remote-check">Maintenance › Remote check</a>.</p><h2 id="connected" tabindex="-1">1. Check that the app is connected to the robot <a class="header-anchor" href="#connected" aria-label="Permalink to &quot;1. Check that the app is connected to the robot {#connected}&quot;">​</a></h2><p>If the section shows <code>Not connected to a robot</code>, the app is not attached to the robot. Remote check is turned on in the robot, so the app must be connected to it directly. Join the robot&#39;s Wi-Fi and connect from the hub (see <a href="/RBQ/nightly/manual/gui/connection.html">Connection</a>).</p><h2 id="router" tabindex="-1">2. Check that the robot router is on the internet <a class="header-anchor" href="#router" aria-label="Permalink to &quot;2. Check that the robot router is on the internet {#router}&quot;">​</a></h2><p>Remote check needs the robot to reach the Rainbow Robotics server. A robot without a USIM needs its router joined to the site Wi-Fi.</p><ol><li>On a device on the robot&#39;s Wi-Fi, open <code>http://192.168.0.1</code> in a browser and go into <code>Setup</code>.</li><li>In <code>Status Summary</code>, check that the internet status says the router is connected over wireless WAN.</li><li>If not, turn on wireless WAN with steps 1–3 of <a href="/RBQ/nightly/manual/operation/robot-internet.html">Connecting the Robot to the Internet</a>.</li></ol><p>A site network that shows a web sign-in page or needs device (MAC) registration does not give wireless WAN internet access. Pick a phone hotspot instead of the site Wi-Fi.</p><h2 id="dns" tabindex="-1">3. Set up the robot&#39;s DNS <a class="header-anchor" href="#dns" aria-label="Permalink to &quot;3. Set up the robot&#39;s DNS {#dns}&quot;">​</a></h2><p>Even with the router on the internet, a robot PC with no name (DNS) server cannot find the Rainbow Robotics server. Take control, then press <code>Set up DNS</code> in the remote check section (<a href="/RBQ/nightly/manual/operation/robot-internet.html#dns">Set up the robot&#39;s DNS</a>).</p><ul><li><em>DNS is set up</em> — go on to the next check.</li><li><em>Take control first, then press it</em> — take control and press it again.</li><li><em>Could not set up DNS</em> — check step 2 (router internet) again. If it still fails, contact support.</li></ul><p>If the button is not there, the robot software is older than this feature. <a href="/RBQ/nightly/manual/gui/software-update.html">Update the robot software</a>.</p><h2 id="register" tabindex="-1">4. Check whether remote registration is needed <a class="header-anchor" href="#register" aria-label="Permalink to &quot;4. Check whether remote registration is needed {#register}&quot;">​</a></h2><p>If the section shows <code>Values needed for the remote connection are missing</code>, the robot has not been registered with the Rainbow Robotics server yet.</p><ol><li>Press <code>Turn on 1h</code>. The <code>Remote registration</code> window opens. Press <code>Register</code>.</li><li>Registration is sent from the device running the app. If <em>Internet is required — the robot LAN may have none. Try again on a network with internet.</em> appears, finish step 2 first. Once the router is on the internet, devices on the robot&#39;s Wi-Fi use that connection too.</li><li>When <em>Registered. Restart the robot, then turn remote check on again.</em> appears, press <code>Restart robot service</code>. The robot must be sitting, and only the device in control can do this.</li><li>When the robot is back, press <code>Turn on 1h</code> again.</li></ol><h2 id="errors" tabindex="-1">5. Turn-on error messages <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;5. Turn-on error messages {#errors}&quot;">​</a></h2><p>You pressed <code>Turn on 1h</code> and red text appears under the buttons.</p><table tabindex="0"><thead><tr><th>Message</th><th>What to do</th></tr></thead><tbody><tr><td><em>Could not turn on — The robot is not connected to the internet</em></td><td>The robot could not reach the Rainbow Robotics server. Check steps 2 and 3. If you just registered, check that the robot service was restarted</td></tr><tr><td><em>Could not turn on — The robot&#39;s SSH server is not running</em></td><td>Turn the robot off and on again. If it persists, contact support</td></tr></tbody></table><h2 id="support" tabindex="-1">6. When you contact support <a class="header-anchor" href="#support" aria-label="Permalink to &quot;6. When you contact support {#support}&quot;">​</a></h2><p>If nothing above helps, send these along:</p><ul><li>The robot serial number (top left of the hub)</li><li>The text shown in the remote check section, word for word</li><li>The internet status from the router&#39;s <code>Status Summary</code></li></ul>',21)])])}const m=t(a,[["render",i]]);export{p as __pageData,m as default};
